    42	    for (let i = 0; i < bbs.length; i++) {
    43	        const bb = bbs[i];
    44	        if (clientXMin <= bb.right && clientXMax >= bb.left && clientYMin <= bb.bottom && clientYMax >= bb.top) {
    45	            return bb;
    46	        }
    47	    }
